const app=createApp();
const server=http.createServer(app);
await new Promise(resolve=>server.listen(0,resolve));
const {port}=server.address();
async function req(path, opts={}) { const res=await fetch("'`http://127.0.0.1:${port}${path}`,opts); return {status:res.status, body:await res.text()}; }
console.log('"'GET /', await req('/'));
console.log('GET /api/appointments unauthenticated', await req('/api/appointments'));
console.log('POST /api/sign-in missing id', await req('/api/sign-in',{method:'POST',headers:{'content-type':'application/json'},body:'{}'}));
console.log('POST /api/sign-in arbitrary id', await req('/api/sign-in',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({patientId:'other'})}));
